{"file_text": "@page "/chat"
@using sv_bcf4bc99295b48adb056714e198fd637.Services
@using sv_bcf4bc99295b48adb056714e198fd637.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(activeThread is not null ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <MessageArea Channel="selectedChannel"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages" />

    @if (activeThread is not null)
    {
        <ThreadPanel RootMessage="activeThread"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = new();
    private Channel? selectedChannel;
    private List<Message> messages = new();
    private List<ThreadSummary> threadSummaries = new();
    private Message? activeThread;
    private List<Message> threadReplies = new();
    private bool isLoadingMore;
    private int messagePageSize = 50;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, messagePageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Compute thread summaries from messages that have replies
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => new ThreadSummary(
                m.Id,
                messages.Count(r => r.ReplyToId == m.Id),
                messages.Where(r => r.ReplyToId == m.Id).Select(r => r.SentAt).DefaultIfEmpty(m.SentAt).Max()))
            .Where(ts => ts.ReplyCount > 0)
            .ToList();

        // Refresh channels to update unread counts
        channels = await ChatService.GetChannelsAsync();
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;
        isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, messagePageSize);
        if (olderMessages.Count > 0)
        {
            messages.InsertRange(0, olderMessages);
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var sent = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(sent);
    }

    private async Task OpenThread(Message rootMessage)
    {
        activeThread = rootMessage;
        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private void CloseThread()
    {
        activeThread = null;
        threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannel is null || activeThread is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, activeThread.Id);
        threadReplies.Add(reply);
        messages.Add(reply);

        // Update thread summary
        var existing = threadSummaries.FirstOrDefault(t => t.RootMessageId == activeThread.Id);
        if (existing is not null)
        {
            threadSummaries.Remove(existing);
        }
        threadSummaries.Add(new ThreadSummary(activeThread.Id, threadReplies.Count, reply.SentAt));
    }

    private async Task HandleReaction(ReactionRequest request)
    {
        await ChatService.AddReactionAsync(request.MessageId, request.Emoji);

        // Update the local message's reactions
        var msg = messages.FirstOrDefault(m => m.Id == request.MessageId);
        if (msg is not null)
        {
            var reaction = msg.Reactions.FirstOrDefault(r => r.Emoji == request.Emoji);
            if (reaction is not null)
            {
                reaction.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(request.Emoji, new List<string> { "You" }));
            }
        }
    }
}
